// План specs/dispatch-sms.md 1.1–1.4 (кейсы .qa/tests/dispatch-sms/DS-01…DS-04). Admin, компания «test», десктоп, EN и HE.
// Только просмотр: форма New Job не сохраняется, «Send SMS» не нажимается (send-sms перехватывается и обрывается).
import { test, expect } from '@playwright/test';
import {
  ADMIN_STATE, JOB, L, Lang, TECH,
  blockSmsSending, expectNoSmsSent, fillJobInfo, openDispatch, openNewJob, pickTechnician, prepare, previewLines,
} from './dispatch-helpers';

test.use({ storageState: ADMIN_STATE });

for (const lang of ['en', 'he'] as Lang[]) {
  const U = lang.toUpperCase();
  const T = L[lang];

  test.describe(`Dispatch: SMS Preview (#5fbb66) ${U}`, () => {
    let smsHits: string[] = [];

    test.beforeEach(async ({ page }) => {
      await prepare(page, lang);
      smsHits = await blockSmsSending(page);
    });

    test.afterEach(() => {
      expectNoSmsSent(smsHits);
    });

    test(`New Job (${U}): has "${T.jobInfoTab}" and Dispatch tabs, Dispatch shows Assign Technician and SMS Preview #5fbb66 @desktop @prod-safe`, async ({ page }) => {
      await openNewJob(page, lang);
      const panel = await openDispatch(page, lang);
      await expect(panel.getByRole('button', { name: T.send })).toBeVisible();
    });

    test(`Dispatch (${U}): SMS Preview contains company, Job Id, client, phone, address, date, type, note and STOP line #5fbb66 @desktop @prod-safe`, async ({ page }) => {
      await openNewJob(page, lang);
      await fillJobInfo(page);
      const panel = await openDispatch(page, lang);
      const lines = await previewLines(panel);

      expect(lines[0]).toBe('Powered by Techory.AI');
      expect(lines[1], 'имя компании').toBe('test');
      expect(lines).toContain(T.jobId);
      expect(lines).toContain(`${T.name} ${JOB.client}`);
      expect(lines).toContain(`${T.phone} ${JOB.phoneE164}`);
      expect(lines).toContain(`${T.address} ${JOB.address}`);
      expect(lines.some((l) => l.startsWith(`${T.date} `) && /\d{4}/.test(l)), `строка «${T.date} …» с датой`).toBe(true);
      expect(lines).toContain(`${T.type} ${JOB.type}`);
      expect(lines).toContain(`${T.note} ${JOB.note}`);
      expect(lines[lines.length - 1]).toBe('Reply STOP to opt out.');
    });

    test(`Dispatch (${U}): without technician "${T.send}" is disabled with hint #5fbb66 @desktop @prod-safe`, async ({ page }) => {
      await openNewJob(page, lang);
      const panel = await openDispatch(page, lang);
      await expect(panel.getByRole('button', { name: T.send })).toBeDisabled();
      await expect(panel.getByText(T.hint, { exact: true })).toBeVisible();
      await expect(panel).not.toContainText(T.recipient);
    });

    test(`Dispatch (${U}): selected technician is shown as recipient and "${T.send}" becomes enabled (not clicked) #5fbb66 @desktop @prod-safe`, async ({ page }) => {
      await openNewJob(page, lang);
      const panel = await openDispatch(page, lang);
      const send = panel.getByRole('button', { name: T.send });

      await pickTechnician(page, panel, lang, TECH.alpha.name);
      await expect(panel).toContainText(new RegExp(`${T.recipient.source}\\s*${TECH.alpha.name}\\s*\\${TECH.alpha.phone}`));
      await expect(panel.getByText(T.hint, { exact: true })).toBeHidden();
      await expect(send).toBeEnabled();

      await pickTechnician(page, panel, lang, TECH.beta.name);
      await expect(panel).toContainText(new RegExp(`${T.recipient.source}[\\s\\S]*${TECH.beta.name}\\s*\\${TECH.beta.phone}`));
      await expect(send).toBeEnabled();
    });
  });
}
